--
-- Name: actions; Type: TABLE; Schema: public; Owner: erpai
--

CREATE TABLE public.actions (
    id bigint NOT NULL,
    created_at timestamp(6) with time zone,
    created_by character varying(255),
    updated_at timestamp(6) with time zone,
    updated_by character varying(255),
    version integer NOT NULL,
    action_code character varying(50) NOT NULL,
    action_name character varying(100) NOT NULL,
    category character varying(30) NOT NULL,
    description character varying(500),
    display_order integer NOT NULL,
    is_system boolean NOT NULL,
    status character varying(20) NOT NULL,
    CONSTRAINT actions_category_check CHECK (((category)::text = ANY ((ARRAY['CRUD'::character varying, 'WORKFLOW'::character varying, 'FINANCIAL'::character varying, 'DATA_IO'::character varying, 'ADMIN'::character varying, 'EXECUTION'::character varying])::text[]))),
    CONSTRAINT actions_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying])::text[])))
);


ALTER TABLE public.actions OWNER TO erpai;

--
-- Name: actions_id_seq; Type: SEQUENCE; Schema: public; Owner: erpai
--

ALTER TABLE public.actions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.actions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


