--
-- Name: users; Type: TABLE; Schema: public; Owner: erpai
--

CREATE TABLE public.users (
    id bigint NOT NULL,
    created_at timestamp(6) with time zone,
    created_by character varying(255),
    updated_at timestamp(6) with time zone,
    updated_by character varying(255),
    version integer NOT NULL,
    activated_at timestamp(6) with time zone,
    branch_id bigint,
    company_id bigint,
    deactivated_at timestamp(6) with time zone,
    department_id bigint,
    email character varying(255) NOT NULL,
    failed_login_attempts integer NOT NULL,
    first_name character varying(100) NOT NULL,
    job_title character varying(100),
    last_login_at timestamp(6) with time zone,
    last_name character varying(100) NOT NULL,
    lock_reason character varying(500),
    locked_at timestamp(6) with time zone,
    locked_until timestamp(6) with time zone,
    password_hash character varying(255) NOT NULL,
    phone_number character varying(20),
    profile_image_url character varying(500),
    status character varying(30) NOT NULL,
    tenant_id bigint NOT NULL,
    username character varying(100) NOT NULL,
    CONSTRAINT users_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING_ACTIVATION'::character varying, 'ACTIVE'::character varying, 'LOCKED'::character varying, 'DEACTIVATED'::character varying, 'ARCHIVED'::character varying])::text[])))
);


ALTER TABLE public.users OWNER TO erpai;

--
-- Name: users_id_seq; Type: SEQUENCE; Schema: public; Owner: erpai
--

ALTER TABLE public.users ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.users_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: warehouses; Type: TABLE; Schema: public; Owner: erpai
--

CREATE TABLE public.warehouses (
    id bigint NOT NULL,
    created_at timestamp(6) with time zone,
    created_by character varying(255),
    updated_at timestamp(6) with time zone,
    updated_by character varying(255),
    version integer NOT NULL,
    company_id bigint NOT NULL,
    tenant_id bigint NOT NULL,
    address character varying(500),
    branch_id bigint,
    code character varying(64) NOT NULL,
    default_marker integer,
    is_active boolean NOT NULL,
    is_default boolean NOT NULL,
    name character varying(255) NOT NULL,
    phone character varying(32),
    type character varying(32) NOT NULL,
    CONSTRAINT warehouses_type_check CHECK (((type)::text = ANY ((ARRAY['GENERAL'::character varying, 'COLD_STORAGE'::character varying, 'TRANSIT'::character varying, 'QUARANTINE'::character varying, 'RETURNS'::character varying, 'SCRAP'::character varying])::text[])))
);


ALTER TABLE public.warehouses OWNER TO erpai;

--
-- Name: warehouses_id_seq; Type: SEQUENCE; Schema: public; Owner: erpai
--

ALTER TABLE public.warehouses ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.warehouses_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


